[{"order":1,"type":"heading","text":"SQL Fundamentals in Oracle DB: SELECT, INSERT, UPDATE, DELETE"},{"order":2,"type":"paragraph","text":"This tutorial covers the fundamental SQL commands for interacting with an Oracle database: SELECT, INSERT, UPDATE, and DELETE. These commands are essential for retrieving, adding, modifying, and removing data from your tables."},{"order":3,"type":"subheading","text":"SELECT Statement: Retrieving Data"},{"order":4,"type":"paragraph","text":"The SELECT statement is used to retrieve data from one or more tables in the database. Its basic syntax is:"},{"order":5,"type":"code","text":"SELECT column1, column2, ... FROM table_name WHERE condition;"},{"order":6,"type":"bullet_point","text":"column1, column2, ...: The columns you want to retrieve. Use '*' to select all columns."},{"order":7,"type":"bullet_point","text":"table_name: The name of the table you are querying."},{"order":8,"type":"bullet_point","text":"WHERE condition: An optional clause that filters the rows based on a specified condition."},{"order":9,"type":"code","text":"-- Example: Select all columns from the 'employees' table
SELECT * FROM employees;

-- Example: Select specific columns (employee_id, first_name, last_name) from the 'employees' table
SELECT employee_id, first_name, last_name FROM employees;

-- Example: Select employees with a salary greater than 50000
SELECT employee_id, first_name, last_name FROM employees WHERE salary > 50000;"},{"order":10,"type":"subheading","text":"INSERT Statement: Adding Data"},{"order":11,"type":"paragraph","text":"The INSERT statement is used to add new rows to a table. Its basic syntax is:"},{"order":12,"type":"code","text":"INSERT INTO table_name (column1, column2, ...) VALUES (value1, value2, ...);"},{"order":13,"type":"bullet_point","text":"table_name: The name of the table you are inserting into."},{"order":14,"type":"bullet_point","text":"column1, column2, ...: The columns you are inserting values into. If you are inserting values into all columns, you can omit the column list."},{"order":15,"type":"bullet_point","text":"value1, value2, ...: The values you are inserting into the corresponding columns."},{"order":16,"type":"code","text":"-- Example: Insert a new employee into the 'employees' table
INSERT INTO employees (employee_id, first_name, last_name, email, salary) VALUES (1001, 'John', 'Doe', 'john.doe@example.com', 60000);

-- Example: Insert a new employee without specifying the columns (assuming all columns are provided in the correct order)
INSERT INTO employees VALUES (1002, 'Jane', 'Smith', 'jane.smith@example.com', 70000, '2023-01-01');"},{"order":17,"type":"subheading","text":"UPDATE Statement: Modifying Data"},{"order":18,"type":"paragraph","text":"The UPDATE statement is used to modify existing rows in a table. Its basic syntax is:"},{"order":19,"type":"code","text":"UPDATE table_name SET column1 = value1, column2 = value2, ... WHERE condition;"},{"order":20,"type":"bullet_point","text":"table_name: The name of the table you are updating."},{"order":21,"type":"bullet_point","text":"column1 = value1, column2 = value2, ...: The columns you are updating and their new values."},{"order":22,"type":"bullet_point","text":"WHERE condition: An optional clause that specifies which rows to update. If omitted, all rows will be updated."},{"order":23,"type":"code","text":"-- Example: Update the salary of employee with employee_id 1001
UPDATE employees SET salary = 65000 WHERE employee_id = 1001;

-- Example: Update the email and salary of all employees in the 'sales' department (assuming there's a 'department' column)
UPDATE employees SET email = 'new_email@example.com', salary = 75000 WHERE department = 'sales';"},{"order":24,"type":"subheading","text":"DELETE Statement: Removing Data"},{"order":25,"type":"paragraph","text":"The DELETE statement is used to remove rows from a table. Its basic syntax is:"},{"order":26,"type":"code","text":"DELETE FROM table_name WHERE condition;"},{"order":27,"type":"bullet_point","text":"table_name: The name of the table you are deleting from."},{"order":28,"type":"bullet_point","text":"WHERE condition: An optional clause that specifies which rows to delete. If omitted, all rows will be deleted (use with caution!)."},{"order":29,"type":"code","text":"-- Example: Delete the employee with employee_id 1002
DELETE FROM employees WHERE employee_id = 1002;

-- Example: Delete all employees in the 'marketing' department (assuming there's a 'department' column)
DELETE FROM employees WHERE department = 'marketing';"},{"order":30,"type":"paragraph","text":"This tutorial provides a basic overview of the fundamental SQL commands. Remember to always test your SQL statements in a development environment before executing them in a production database."}]
